<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../config/session.php';

start_app_session();
$pdo = database();
$adminProfile = require_signed_in('admin');

$successMessage = '';
$errorMessage = '';
$suspensionToast = '';
$reactivationToast = '';

if (!empty($_GET['landlord_created'])) {
    $successMessage = 'Landlord account for ' . htmlspecialchars($_GET['landlord_created'], ENT_QUOTES, 'UTF-8') . ' was successfully created and verified!';
}

if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'delete_user') {
    $targetId = trim((string)($_POST['target_user_id'] ?? ''));
    $targetRole = trim((string)($_POST['target_role'] ?? ''));
    if ($targetRole === 'admin' && (string)$targetId === (string)$adminProfile['id']) {
        $errorMessage = 'You cannot delete your own admin account while signed in.';
    } elseif ($targetId !== '') {
        $delRes = delete_user_account_completely($pdo, $targetId, $targetRole ?: null);
        if ($delRes['ok']) {
            $successMessage = "Account {$targetId} and all associated listings, rooms, bookings, applications, and activity were completely deleted from everywhere.";
        } else {
            $errorMessage = $delRes['message'];
        }
    }
} elseif ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'suspend_user') {
    $targetId = trim((string)($_POST['target_user_id'] ?? ''));
    $targetRole = trim((string)($_POST['target_role'] ?? ''));
    $reason = trim((string)($_POST['suspension_reason'] ?? ''));
    if ($targetRole === 'admin') {
        $errorMessage = 'Administrative accounts cannot be suspended.';
    } elseif ($targetId !== '') {
        $res = admin_suspend_user($pdo, $targetId, $targetRole, $reason);
        if ($res['ok']) {
            if ($targetRole === 'landlord') {
                $nameStmt = $pdo->prepare('SELECT first_name, last_name FROM landlords WHERE landlord_id = ? LIMIT 1');
                $nameStmt->execute([$targetId]);
                $landlordName = $nameStmt->fetch(PDO::FETCH_ASSOC) ?: [];
                $displayName = trim(($landlordName['first_name'] ?? '') . ' ' . ($landlordName['last_name'] ?? ''));
                $suspensionToast = ($displayName !== '' ? $displayName : 'Landlord') . "'s account has been suspended. Listings are now hidden from student search.";
            } elseif ($targetRole === 'tenant') {
                $nameStmt = $pdo->prepare('SELECT first_name, last_name FROM tenants WHERE tenant_id = ? LIMIT 1');
                $nameStmt->execute([$targetId]);
                $tenantName = $nameStmt->fetch(PDO::FETCH_ASSOC) ?: [];
                $displayName = trim(($tenantName['first_name'] ?? '') . ' ' . ($tenantName['last_name'] ?? ''));
                $suspensionToast = ($displayName !== '' ? $displayName : 'Tenant') . " has been suspended.";
            } else {
                $successMessage = $res['message'];
            }
        } else {
            $errorMessage = $res['message'];
        }
    }
} elseif ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'unsuspend_user') {
    $targetId = trim((string)($_POST['target_user_id'] ?? ''));
    $targetRole = trim((string)($_POST['target_role'] ?? ''));
    if ($targetId !== '') {
        $res = admin_unsuspend_user($pdo, $targetId, $targetRole);
        if ($res['ok']) {
            if ($targetRole === 'tenant') {
                $nameStmt = $pdo->prepare('SELECT first_name, last_name FROM tenants WHERE tenant_id = ? LIMIT 1');
                $nameStmt->execute([$targetId]);
                $tenantName = $nameStmt->fetch(PDO::FETCH_ASSOC) ?: [];
                $displayName = trim(($tenantName['first_name'] ?? '') . ' ' . ($tenantName['last_name'] ?? ''));
                $reactivationToast = ($displayName !== '' ? $displayName : 'Tenant') . ' has been reactivated.';
            } else {
                $successMessage = $res['message'];
            }
        } else {
            $errorMessage = $res['message'];
        }
    }
}

// Search & Filter
$search = trim($_GET['search'] ?? '');
$roleFilter = $_GET['role'] ?? 'all';
$statusFilter = strtolower(trim((string)($_GET['status'] ?? 'all')));
if (!in_array($statusFilter, ['all', 'unverified', 'verified', 'suspended', 'staff'], true)) {
    $statusFilter = 'all';
}

$sql = "SELECT tenant_id AS id, tenant_id AS code, first_name, last_name, email, email AS personal_email, phone_number, 'tenant' AS role, verification_status, account_status, suspension_reason, suspended_at, profile_photo, created_at FROM tenants
        UNION ALL
        SELECT landlord_id AS id, landlord_id AS code, first_name, last_name, email, email AS personal_email, phone_number, 'landlord' AS role, status AS verification_status, (CASE WHEN status = 'suspended' THEN 'suspended' ELSE 'active' END) AS account_status, suspension_reason, suspended_at, profile_photo, created_at FROM landlords
        UNION ALL
        SELECT admin_id AS id, admin_id AS code, first_name, last_name, email, email AS personal_email, phone_number, 'admin' AS role, 'verified' AS verification_status, 'active' AS account_status, NULL AS suspension_reason, NULL AS suspended_at, profile_photo, created_at FROM admins";

$wrapSql = "SELECT * FROM ($sql) AS u WHERE 1=1";
$params = [];

$roleFilter = strtolower(trim((string)($_GET['role'] ?? 'all')));
if (!in_array($roleFilter, ['all', 'landlord', 'tenant', 'admin'], true)) {
    $roleFilter = 'all';
}

$wrapSql .= " ORDER BY created_at DESC, id DESC";
$stmt = $pdo->prepare($wrapSql);
$stmt->execute($params);
$users = $stmt->fetchAll(PDO::FETCH_ASSOC);

// Map base emails to existing profile photos to resolve alias accounts
$userPhotoMap = [];
$knownFallbackPhotos = [
    'noerlyyvonnemaeaya@gmail.com' => 'https://lh3.googleusercontent.com/a/ACg8ocKMNuwR00XMRnkTOAfbTI9-Mj4oMVePm-m2Hjvsc9xGl-mGErM=s96-c',
    'noerlyyvonnemaeidos@gmail.com' => 'https://lh3.googleusercontent.com/a/ACg8ocLkfJ4H9h7oxO6Q-8rimQh91t-_ymgg_JizrHpZZvsyB4QuYSKsgw=s96-c',
    'idosng.877.stud@cdd.edu.ph' => 'https://lh3.googleusercontent.com/a/ACg8ocIa5uoNxlGFPIWJxZ3TuGuDTO4zWRxN6Jf3pZtFez06J7S2ZO0=s96-c',
    'unistaysads@gmail.com' => 'https://lh3.googleusercontent.com/a/ACg8ocI3KKQnBe0wpyMq1V9xiRUR1qHFa2JCMDkaCZ3eqq6ogLx9GYM=s96-c',
    'unistayinspector@gmail.com' => 'https://lh3.googleusercontent.com/a/ACg8ocL0nQ9A9XqXheuj_GqNOyFgJz6zmfJpRswyI-BRaGk1lWhAjQY=s96-c'
];
foreach ($knownFallbackPhotos as $kEmail => $kPhoto) {
    $userPhotoMap[$kEmail] = $kPhoto;
}
foreach ($users as $cand) {
    $candPhoto = resolve_user_profile_photo_url($cand['profile_photo'] ?? null, null, $cand['role'] ?? '');
    if (!empty($candPhoto)) {
        $candEmail = strtolower(trim((string)($cand['email'] ?? '')));
        if ($candEmail !== '') {
            $userPhotoMap[$candEmail] = $candPhoto;
            $candBase = preg_replace('/\+[^@]+(@.*)$/', '$1', $candEmail);
            if (!isset($userPhotoMap[$candBase])) {
                $userPhotoMap[$candBase] = $candPhoto;
            }
        }
    }
}

// Counts for sliding tabs
$countAll = (int)$pdo->query("SELECT (SELECT COUNT(*) FROM tenants) + (SELECT COUNT(*) FROM landlords) + (SELECT COUNT(*) FROM admins)")->fetchColumn();
$countLandlords = (int)$pdo->query("SELECT COUNT(*) FROM landlords")->fetchColumn();
$countTenants = (int)$pdo->query("SELECT COUNT(*) FROM tenants")->fetchColumn();
$countAdmins = (int)$pdo->query("SELECT COUNT(*) FROM admins")->fetchColumn();

// Administrator profile metadata
$adminInitials = strtoupper(substr($adminProfile['name'] ?? 'A', 0, 1) . substr(strstr($adminProfile['name'] ?? '', ' ') ?: ($adminProfile['name'] ?? 'A'), 1, 1));
if (strlen($adminInitials) < 2) $adminInitials = strtoupper(substr($adminProfile['name'] ?? 'AD', 0, 2));
$effectiveAvatar = resolve_user_profile_photo_url($adminProfile['photo'] ?? null);
?>
