    <script>
    (() => {
        // Sliding Brown Indicator matching Tenant Dorms interaction
        const catBar = document.querySelector('.topbar-categories-bar');
        const catIndicator = catBar ? catBar.querySelector('.topbar-cat-indicator') : null;
        const catTabs = catBar ? Array.from(catBar.querySelectorAll('.topbar-cat-tab')) : [];
        let catIndicatorReady = false;

        function placeCatIndicator(targetTab, instant) {
            if (!catIndicator || !catBar) return;
            const tab = targetTab || catBar.querySelector('.topbar-cat-tab.is-active') || catTabs[0];
            if (!tab) return;
            const barRect = catBar.getBoundingClientRect();
            const tabRect = tab.getBoundingClientRect();
            const left = tabRect.left - barRect.left;
            const width = tabRect.width;

            if (instant || !catIndicatorReady) {
                catIndicator.style.transition = 'none';
                catIndicator.style.width = width + 'px';
                catIndicator.style.transform = 'translateX(' + left + 'px)';
                catIndicator.offsetHeight; // force reflow
                catIndicator.style.transition = '';
                catIndicatorReady = true;
            } else {
                catIndicator.style.width = width + 'px';
                catIndicator.style.transform = 'translateX(' + left + 'px)';
            }
        }

        function filterUsersByRole(role) {
            const rows = document.querySelectorAll('#users-table-body tr.user-row');
            const query = (document.getElementById('user-search')?.value || '').trim().toLowerCase();
            const status = document.getElementById('user-status-filter')?.dataset.status || 'all';
            let visibleCount = 0;
            rows.forEach(function(row) {
                const rowRole = row.getAttribute('data-role');
                const matches = (role === 'all' || rowRole === role) && (status === 'all' || row.dataset.status === status) && (!query || (row.dataset.search || '').includes(query));
                row.style.display = matches ? '' : 'none';
                if (matches) visibleCount++;
            });

            const emptyRow = document.getElementById('users-empty-row');
            if (emptyRow) {
                emptyRow.style.display = (visibleCount === 0) ? '' : 'none';
            }
        }

        document.getElementById('user-search')?.addEventListener('input', function() {
            filterUsersByRole(document.querySelector('.topbar-cat-tab.is-active')?.dataset.role || 'all');
        });
        const statusSelect = document.getElementById('user-status-filter');
        const statusButton = statusSelect?.querySelector('.um-select-btn');
        const statusMenu = statusSelect?.querySelector('.um-select-menu');
        const statusOptions = Array.from(statusMenu?.querySelectorAll('[role="option"]') || []);
        let statusMenuTimer;
        const closeStatusMenu = (returnFocus = false) => {
            if (!statusMenu || statusMenu.hidden) return;
            clearTimeout(statusMenuTimer);
            statusButton.setAttribute('aria-expanded', 'false');
            statusMenu.classList.add('is-closing');
            statusMenuTimer = setTimeout(() => {
                statusMenu.hidden = true;
                statusMenu.classList.remove('is-closing');
                if (returnFocus) statusButton.focus();
            }, 160);
        };
        const openStatusMenu = (focusOption = false) => {
            clearTimeout(statusMenuTimer);
            statusMenu.classList.remove('is-closing');
            statusMenu.hidden = false;
            statusButton.setAttribute('aria-expanded', 'true');
            if (focusOption) (statusOptions.find(option => option.getAttribute('aria-selected') === 'true') || statusOptions[0])?.focus();
        };
        const chooseStatus = option => {
            const status = option.dataset.value || 'all';
            statusSelect.dataset.status = status;
            statusSelect.querySelector('.um-select-value').textContent = option.textContent;
            statusOptions.forEach(item => item.setAttribute('aria-selected', String(item === option)));
            document.getElementById('hiddenStatusFilter').value = status;
            filterUsersByRole(document.querySelector('.topbar-cat-tab.is-active')?.dataset.role || 'all');
            const url = new URL(window.location);
            if (status === 'all') url.searchParams.delete('status');
            else url.searchParams.set('status', status);
            window.history.pushState({}, '', url);
            closeStatusMenu(true);
        };
        statusButton?.addEventListener('click', () => statusMenu.hidden ? openStatusMenu() : closeStatusMenu());
        statusButton?.addEventListener('keydown', event => {
            if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
                event.preventDefault();
                openStatusMenu(true);
            } else if (event.key === 'Escape') {
                closeStatusMenu();
            }
        });
        statusOptions.forEach(option => option.addEventListener('click', () => chooseStatus(option)));
        statusMenu?.addEventListener('keydown', event => {
            const current = statusOptions.indexOf(document.activeElement);
            if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
                event.preventDefault();
                statusOptions[(current + (event.key === 'ArrowDown' ? 1 : -1) + statusOptions.length) % statusOptions.length].focus();
            } else if (event.key === 'Home' || event.key === 'End') {
                event.preventDefault();
                statusOptions[event.key === 'Home' ? 0 : statusOptions.length - 1].focus();
            } else if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                if (current >= 0) chooseStatus(statusOptions[current]);
            } else if (event.key === 'Escape') {
                event.preventDefault();
                closeStatusMenu(true);
            } else if (event.key === 'Tab') {
                closeStatusMenu();
            }
        });
        document.addEventListener('click', event => {
            if (statusSelect && !statusSelect.contains(event.target)) closeStatusMenu();
        });
        filterUsersByRole(document.querySelector('.topbar-cat-tab.is-active')?.dataset.role || 'all');

        if (catBar && catTabs.length) {
            window.addEventListener('load', function() {
                placeCatIndicator(null, true);
            });
            setTimeout(function() {
                placeCatIndicator(null, true);
            }, 60);
            window.addEventListener('resize', function() {
                placeCatIndicator(null, true);
            });

            catTabs.forEach(function(tab) {
                tab.addEventListener('click', function(e) {
                    e.preventDefault();
                    catTabs.forEach(function(b) {
                        b.classList.remove('is-active');
                        b.setAttribute('aria-selected', 'false');
                    });
                    tab.classList.add('is-active');
                    tab.setAttribute('aria-selected', 'true');
                    placeCatIndicator(tab, false);

                    const role = tab.getAttribute('data-role') || 'all';
                    filterUsersByRole(role);

                    const hiddenRoleInput = document.getElementById('hiddenRoleFilter');
                    if (hiddenRoleInput) {
                        hiddenRoleInput.value = role;
                    }

                    // Update URL without page reload
                    const url = new URL(window.location);
                    if (role === 'all') {
                        url.searchParams.delete('role');
                    } else {
                        url.searchParams.set('role', role);
                    }
                    window.history.pushState({}, '', url);
                });
            });
        }

        // Suspend Modal Controls
        const suspendModal = document.getElementById('suspend-modal');
        const suspendCloseBtn = document.getElementById('suspend-dialog-close');
        const suspendCancelBtn = document.getElementById('suspend-cancel-btn');
        const suspendTargetId = document.getElementById('suspend-target-id');
        const suspendTargetRole = document.getElementById('suspend-target-role');
        const suspendTargetName = document.getElementById('suspend-target-name');
        const suspendReason = document.getElementById('suspension_reason');

        window.openSuspendModal = function(id, name, role, code) {
            if (!suspendModal) return;
            suspendTargetId.value = id;
            suspendTargetRole.value = role;
            suspendTargetName.textContent = name;
            if (suspendReason) suspendReason.value = '';
            suspendModal.showModal();
        };

        if (suspendCloseBtn && suspendModal) suspendCloseBtn.addEventListener('click', () => suspendModal.close());
        if (suspendCancelBtn && suspendModal) suspendCancelBtn.addEventListener('click', () => suspendModal.close());
        if (suspendModal) {
            suspendModal.addEventListener('click', (e) => {
                const rect = suspendModal.getBoundingClientRect();
                if (e.clientX < rect.left || e.clientX > rect.right || e.clientY < rect.top || e.clientY > rect.bottom) {
                    suspendModal.close();
                }
            });
        }

        const unsuspendModal = document.getElementById('unsuspend-modal');
        document.querySelectorAll('.btn-unsuspend-user').forEach(function(button) {
            button.addEventListener('click', function() {
                document.getElementById('unsuspend-target-id').value = button.dataset.userId || '';
                document.getElementById('unsuspend-target-role').value = button.dataset.userRole || '';
                document.getElementById('unsuspend-target-name').textContent = button.dataset.userName || '';
                unsuspendModal.showModal();
            });
        });
        document.getElementById('unsuspend-dialog-close')?.addEventListener('click', () => unsuspendModal.close());
        document.getElementById('unsuspend-cancel-btn')?.addEventListener('click', () => unsuspendModal.close());
        unsuspendModal?.addEventListener('click', function(event) {
            const rect = unsuspendModal.getBoundingClientRect();
            if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) {
                unsuspendModal.close();
            }
        });
    })();
    </script>
    <?php if ($suspensionToast !== ''): ?>
    <div class="notification-toast" id="suspensionToast" role="status" style="border-left:4px solid #dc2626; cursor:pointer;">
        <strong>Account Suspended</strong>
        <span><?= htmlspecialchars($suspensionToast, ENT_QUOTES, 'UTF-8') ?></span>
    </div>
    <script>
    (() => {
        const toast = document.getElementById('suspensionToast');
        if (!toast) return;
        const hide = () => {
            toast.classList.remove('is-visible');
            setTimeout(() => toast.remove(), 400);
        };
        toast.addEventListener('click', hide);
        requestAnimationFrame(() => requestAnimationFrame(() => toast.classList.add('is-visible')));
        setTimeout(hide, 4500);
    })();
    </script>
    <?php endif; ?>
    <?php if ($reactivationToast !== ''): ?>
    <div class="notification-toast toast-light-brown" id="reactivationToast" role="status">
        <div class="toast-header">
            <strong>Account Reactivated</strong>
            <button type="button" class="toast-close-btn" aria-label="Close notification" onclick="document.getElementById('reactivationToast')?.classList.remove('is-visible'); setTimeout(() => document.getElementById('reactivationToast')?.remove(), 400);">&times;</button>
        </div>
        <span><?= htmlspecialchars($reactivationToast, ENT_QUOTES, 'UTF-8') ?></span>
    </div>
    <script>
    (() => {
        const toast = document.getElementById('reactivationToast');
        if (!toast) return;
        const hide = () => {
            toast.classList.remove('is-visible');
            setTimeout(() => toast.remove(), 400);
        };
        toast.addEventListener('click', hide);
        requestAnimationFrame(() => requestAnimationFrame(() => toast.classList.add('is-visible')));
        setTimeout(hide, 4500);
    })();
    </script>
    <?php endif; ?>
</body>
</html>
